scripts.script:
local library = loadstring(game:HttpGet("https://raw.githubusercontent.com/xHeptc/Kavo-UI-Library/main/source.lua"))()
local window = library.CreateLib("OpScripts - Lethal ape", "DarkTheme")
local tab = window:NewTab("Main")
local section = tab:NewSection("Main")

section:NewButton("KICK ALL (Patched)", "Kicks everyone! SERVER SIDED", function()
    workspace.OwnerPanel.AdminPanelGui.Events.ShutdownEvent:FireServer()
end)

section:NewButton("Zoom out", "Lets you zoom out", function()
    game.Players.LocalPlayer.CameraMode = Enum.CameraMode.Classic
end)

local antimodactive = false
local modlist = {"gubdev", "anothermod", "badplayer"}

section:NewToggle("Anti Mod", "Makes you leave if a mod is in", function(state)
    antimodactive = state
end)

local function checkplayer(player)
    if antimodactive then
        for _, name in pairs(modlist) do
            if player.Name == name then
                game.Players.LocalPlayer:Kick("OpScripts - anti mod")
                break
            end
        end
    end
end

for _, player in pairs(game.Players:GetPlayers()) do
    if player.Name == "hteigdpi" then
        game.StarterGui:SetCore("SendNotification", {
            Title = "Alert";
            Text = "The owner of the script is in!";
            Duration = 5;
        })
    end
    checkplayer(player)
end

game.Players.PlayerAdded:Connect(function(player)
    if player.Name == "hteigdpi" then
        game.StarterGui:SetCore("SendNotification", {
            Title = "Alert";
            Text = "The owner of the script is in!";
            Duration = 5;
        })
    end
    checkplayer(player)
end)
